const table = document.querySelector('#grid tbody');

export function renderRows(rows) {
  table.innerHTML = '';

  for (const row of rows) {
    const tr = document.createElement('tr');
    tr.innerHTML = `
      <td>${row.id}</td>
      <td>${row.name}</td>
      <td><button class="select">Seleccionar</button></td>
    `;

    // Un listener por fila: con 5.000 filas son 5.000 listeners.
    tr.querySelector('.select').addEventListener('click', () => {
      document.querySelector('#selected').textContent = row.name;
    });

    table.appendChild(tr);
  }
}

renderRows(window.__ROWS__);

