// Genera 5.000 filas y mide el tiempo de renderizado.
window.__ROWS__ = Array.from({ length: 5000 }, (_, i) => ({
  id: i + 1,
  name: `Fila ${i + 1}`,
}));

window.__measure__ = (label, fn) => {
  const start = performance.now();
  fn();
  console.log(`${label}: ${(performance.now() - start).toFixed(1)}ms`);
};

