const table = document.querySelector('#grid tbody');
const selected = document.querySelector('#selected');

export function renderRows(rows) {
  table.innerHTML = '';

  for (const row of rows) {
    const tr = document.createElement('tr');
    tr.dataset.name = row.name;
    tr.innerHTML = `
      <td>${row.id}</td>
      <td>${row.name}</td>
      <td><button class="select" data-action="select">Seleccionar</button></td>
    `;
    table.appendChild(tr);
  }
}

table.addEventListener('click', (event) => {
  const button = event.target.closest('[data-action="select"]');
  if (!button) return;

  selected.textContent = button.closest('tr').dataset.name;
});

renderRows(window.__ROWS__);

